DROP TABLE IF EXISTS `t_api_key`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_api_key` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '所属用户ID',
  `key_value` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'API Key 值(sk-xxx)',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Key 名称',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0-禁用 1-启用',
  `total_quota` bigint NOT NULL DEFAULT '-1' COMMENT '总Token额度(-1不限制)',
  `used_quota` bigint NOT NULL DEFAULT '0' COMMENT '已用Token数',
  `expired_at` datetime DEFAULT NULL COMMENT '过期时间(NULL永不过期)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `channel_id` bigint DEFAULT NULL COMMENT 'Key绑定渠道（null=系统负载均衡）',
  `used_money` decimal(12,6) DEFAULT '0.000000' COMMENT '已用金额（元）',
  `key_type` tinyint NOT NULL DEFAULT '2' COMMENT '1=Token额度型 2=金额消费型',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_key_value` (`key_value`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='平台 API Key';
/*!40101 SET character_set_client = @saved_cs_client */;

