--
-- Table structure for table `t_call_log`
--

DROP TABLE IF EXISTS `t_call_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_call_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `api_key_id` bigint DEFAULT NULL COMMENT '平台 API Key ID',
  `channel_id` bigint DEFAULT NULL COMMENT '渠道ID',
  `channel_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '渠道名称(冗余)',
  `model_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求模型名',
  `real_model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '实际转发模型名',
  `request_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求唯一ID(UUID)',
  `client_ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '客户端IP',
  `prompt_tokens` int NOT NULL DEFAULT '0' COMMENT '输入 Token 数',
  `completion_tokens` int NOT NULL DEFAULT '0' COMMENT '输出 Token 数',
  `total_tokens` int NOT NULL DEFAULT '0' COMMENT '总 Token 数',
  `cost` decimal(12,6) NOT NULL DEFAULT '0.000000' COMMENT '费用估算(元)',
  `duration_ms` int NOT NULL DEFAULT '0' COMMENT '请求耗时(ms)',
  `http_status` int DEFAULT NULL COMMENT 'HTTP 状态码',
  `is_stream` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否流式: 0-否 1-是',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '调用状态: 0-失败 1-成功',
  `error_msg` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '错误信息',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '调用时间',
  `cache_creation_tokens` int NOT NULL DEFAULT '0' COMMENT '缓存创建Token数',
  `cache_read_tokens` int NOT NULL DEFAULT '0' COMMENT '缓存命中Token数',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_api_key_id` (`api_key_id`) USING BTREE,
  KEY `idx_channel_id` (`channel_id`) USING BTREE,
  KEY `idx_model_name` (`model_name`) USING BTREE,
  KEY `idx_created_at` (`created_at`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=13398 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='调用日志';
/*!40101 SET character_set_client = @saved_cs_client */;

