--
-- Table structure for table `t_channel`
--

DROP TABLE IF EXISTS `t_channel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_channel` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '渠道名称',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型: openai/azure/wenxin/qianwen/custom',
  `base_url` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'API 基础 URL',
  `api_key` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '渠道 API Key (AES 加密存储)',
  `models` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '支持模型列表(JSON数组)',
  `weight` int NOT NULL DEFAULT '1' COMMENT '负载均衡权重',
  `priority` int NOT NULL DEFAULT '0' COMMENT '优先级(越大越优先)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0-禁用 1-启用',
  `timeout_ms` int NOT NULL DEFAULT '30000' COMMENT '请求超时(ms)',
  `health_status` tinyint NOT NULL DEFAULT '1' COMMENT '健康状态: 0-异常 1-正常',
  `last_check_at` datetime DEFAULT NULL COMMENT '上次健康检测时间',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `total_money` decimal(12,4) DEFAULT '0.0000' COMMENT '渠道总预算（元）',
  `used_money` decimal(12,6) DEFAULT '0.000000' COMMENT '渠道已用金额（元）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='第三方 AI 渠道';
/*!40101 SET character_set_client = @saved_cs_client */;

--
